// 主题伴侣的小部件，单独当酒馆助手脚本用。代码从 GitHub 载入，作者更新后自动跟上（最多晚半天）。
// 选项在下面的「脚本变量」里改。和主题伴侣同时装着时不会重复：伴侣里开着同一个小部件就让给伴侣。
const SRC = 'https://testingcf.jsdelivr.net/gh/liangsheng-sys/SillyTavern-Theme-Companion@main/widgets/standalone.js';
const where = { type: 'script', script_id: getScriptId() };
const store = { get: () => getVariables(where), set: d => replaceVariables(d, where) };
let stop = null, gone = false;
$(async () => {
  try {
    // 在酒馆主页面里载入（小部件要操作的是主页面，不是脚本自己的小窗口）
    const load = window.parent.Function('u', 'return import(u)');
    const s = await (await load(SRC)).default({ id: 'room', store });
    if (gone) s(); else stop = s;
  } catch (e) {
    console.error('[小部件] 载入失败', e);
    toastr.error(String(e?.message || e), '小部件载入失败');
  }
});
$(window).on('pagehide', () => { gone = true; stop?.(); });
